orig_text:
leaf co-routed {
         when "/te:te/te:tunnels/te:tunnel/te:bidirectional = 'true'" {
           description
             "Applicable to bidirectional tunnels only.";
         }
         type boolean;
         default "false";
         description
           "When set to true, indicates whether the reverse path must
            be co-routed with the primary.";
       }

